# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span

OPENING = Span(540, 1020)


class FindGapsTests(unittest.TestCase):
    def test_nobody_working_leaves_the_whole_day(self):
        self.assertEqual(find_gaps([], OPENING), ["gap 09:00-17:00 (480 min)"])

    def test_fully_covered_has_no_gaps(self):
        self.assertEqual(find_gaps([OPENING], OPENING), [])

    def test_lunch_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(find_gaps(worked, OPENING), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            find_gaps(worked, OPENING),
            ["gap 09:00-10:00 (60 min)", "gap 15:00-17:00 (120 min)"],
        )

    def test_touching_spans_leave_no_gap(self):
        worked = [Span(540, 720), Span(720, 1020)]
        self.assertEqual(find_gaps(worked, OPENING), [])

    def test_overlapping_spans_are_merged_before_finding_gaps(self):
        worked = [Span(540, 700), Span(650, 760), Span(800, 1020)]
        self.assertEqual(find_gaps(worked, OPENING), ["gap 12:40-13:20 (40 min)"])

    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 720)], OPENING)

    def test_span_running_past_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(900, 1080)], OPENING)

    def test_span_entirely_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(0, 60)], OPENING)
